function quantityAllowance(){
  const settings=quantityAllowanceSettings();if(!settings)return null;
  const included=Math.max(0,Math.floor(Number(settings.quantityLimit)||0));
  if(!included)return null;
  const submitted=tabOrders.filter(order=>order.status!=='cancelled').reduce((sum,order)=>sum+(order.items||[]).reduce((itemSum,item)=>itemSum+(Number(item.quantity)||0),0),0);
  const inCart=cartTotals().count;
  return{included,submitted,inCart,remaining:Math.max(0,included-submitted-inCart)};
}
